"""
Generates the per-dialect Liquibase "formatted SQL" changelogs of sangam-persistence from ONE portable table
catalogue (TABLES below), so the five dialects can never drift apart (A-15, D-54, R12, D-7).

    python -I tools/generate_changelogs.py        (run from sangam/sangam-persistence)

Output: src/main/resources/db/changelog/<dbms>/sangam-0001-baseline.sql for postgresql, oracle, mssql, mysql, h2.
The generated files are committed; Liquibase never runs this script. Change a table here, re-run, and add the
change as a NEW changeset file (never edit an applied changeset; Liquibase checksums would fail).

Type tokens (same meaning as org.sangam.core.layer.Dialect, plus H2):
  {str} 255 chars, {str64}, {str32}, {str1k} 1000 chars, {text} unbounded text, {blob}, {bytes32} 32-byte hash,
  {long}, {int}, {small} (booleans are 0/1), {money} money as BIGINT minor units of the row currency (SD-398; never a decimal),
  {dec} legacy NUMERIC(19,4) (no money column may use it: MoneyColumnGuardTest), {ts} timestamp (UTC), {identity}.
"""
import os

DIALECTS = {
    "postgresql": {
        "{vc80}": "VARCHAR(80)",
        "{date}": "DATE", "{num24_6}": "NUMERIC(24,6)", "{num12_6}": "NUMERIC(12,6)",
        "{vc8}": "VARCHAR(8)", "{vc16}": "VARCHAR(16)", "{vc40}": "VARCHAR(40)", "{asciistr}": "VARCHAR(255)",
        "{str}": "VARCHAR(255)", "{str64}": "VARCHAR(64)", "{str32}": "VARCHAR(32)", "{str1k}": "VARCHAR(1000)",
        "{text}": "TEXT", "{blob}": "BYTEA", "{bytes32}": "BYTEA", "{long}": "BIGINT", "{int}": "INTEGER",
        "{small}": "SMALLINT", "{money}": "BIGINT", "{dec}": "NUMERIC(19,4)", "{ts}": "TIMESTAMP WITH TIME ZONE",
        "{identity}": "BIGINT GENERATED BY DEFAULT AS IDENTITY",
    },
    "oracle": {
        "{vc80}": "VARCHAR2(80 CHAR)",
        "{date}": "DATE", "{num24_6}": "NUMBER(24,6)", "{num12_6}": "NUMBER(12,6)",
        "{vc8}": "VARCHAR2(8 CHAR)", "{vc16}": "VARCHAR2(16 CHAR)", "{vc40}": "VARCHAR2(40 CHAR)", "{asciistr}": "VARCHAR2(255 CHAR)",
        "{str}": "VARCHAR2(255 CHAR)", "{str64}": "VARCHAR2(64 CHAR)", "{str32}": "VARCHAR2(32 CHAR)",
        "{str1k}": "VARCHAR2(1000 CHAR)", "{text}": "CLOB", "{blob}": "BLOB", "{bytes32}": "RAW(32)",
        "{long}": "NUMBER(19)", "{int}": "NUMBER(10)", "{small}": "NUMBER(5)", "{money}": "NUMBER(19)", "{dec}": "NUMBER(19,4)",
        "{ts}": "TIMESTAMP WITH TIME ZONE", "{identity}": "NUMBER(19) GENERATED BY DEFAULT AS IDENTITY",
    },
    "mssql": {
        "{vc80}": "NVARCHAR(80)",
        "{date}": "DATE", "{num24_6}": "DECIMAL(24,6)", "{num12_6}": "DECIMAL(12,6)",
        "{vc8}": "NVARCHAR(8)", "{vc16}": "NVARCHAR(16)", "{vc40}": "NVARCHAR(40)", "{asciistr}": "NVARCHAR(255)",
        "{str}": "NVARCHAR(255)", "{str64}": "NVARCHAR(64)", "{str32}": "NVARCHAR(32)", "{str1k}": "NVARCHAR(1000)",
        "{text}": "NVARCHAR(MAX)", "{blob}": "VARBINARY(MAX)", "{bytes32}": "VARBINARY(32)", "{long}": "BIGINT",
        "{int}": "INT", "{small}": "SMALLINT", "{money}": "BIGINT", "{dec}": "DECIMAL(19,4)", "{ts}": "DATETIMEOFFSET",
        "{identity}": "BIGINT IDENTITY(1,1)",
    },
    # MySQL 8.4: InnoDB, utf8mb4 / utf8mb4_bin on every table. {ts} is DATETIME(6) holding UTC (>= the DATETIME(3)
    # floor of P-1; 6 because the core AuditChain stores microseconds in its hashed envelope).
    "mysql": {
        "{vc80}": "VARCHAR(80)",
        "{date}": "DATE", "{num24_6}": "DECIMAL(24,6)", "{num12_6}": "DECIMAL(12,6)",
        "{vc8}": "VARCHAR(8)", "{vc16}": "VARCHAR(16)", "{vc40}": "VARCHAR(40)",
        "{asciistr}": "VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin",
        "{str}": "VARCHAR(255)", "{str64}": "VARCHAR(64)", "{str32}": "VARCHAR(32)", "{str1k}": "VARCHAR(1000)",
        "{text}": "LONGTEXT", "{blob}": "LONGBLOB", "{bytes32}": "VARBINARY(32)", "{long}": "BIGINT", "{int}": "INT",
        "{small}": "SMALLINT", "{money}": "BIGINT", "{dec}": "DECIMAL(19,4)", "{ts}": "DATETIME(6)", "{identity}": "BIGINT AUTO_INCREMENT",
    },
    # H2 2.3 (development only). The product layer needs MODE=PostgreSQL (see README).
    "h2": {
        "{vc80}": "VARCHAR(80)",
        "{date}": "DATE", "{num24_6}": "NUMERIC(24,6)", "{num12_6}": "NUMERIC(12,6)",
        "{vc8}": "VARCHAR(8)", "{vc16}": "VARCHAR(16)", "{vc40}": "VARCHAR(40)", "{asciistr}": "VARCHAR(255)",
        "{str}": "VARCHAR(255)", "{str64}": "VARCHAR(64)", "{str32}": "VARCHAR(32)", "{str1k}": "VARCHAR(1000)",
        "{text}": "CHARACTER LARGE OBJECT", "{blob}": "BINARY LARGE OBJECT", "{bytes32}": "VARBINARY(32)", "{long}": "BIGINT", "{int}": "INTEGER",
        "{small}": "SMALLINT", "{money}": "BIGINT", "{dec}": "NUMERIC(19,4)", "{ts}": "TIMESTAMP WITH TIME ZONE",
        "{identity}": "BIGINT GENERATED BY DEFAULT AS IDENTITY",
    },
}

