# Column names of module reference DDL that are reserved words on one dialect. They are created QUOTED there so the
# changelog applies everywhere; the owning module must rename them (reported to the integrator), because unquoted SQL
# in the module's code fails on that dialect. Oracle quoted identifiers are upper case so unquoted access is unchanged
# except for the keyword itself.
QUOTED = {
    # empty: no column needs quoting; add entries only as a temporary fallback
}


def q(dbms, name):
    if name.lower() not in QUOTED.get(dbms, set()):
        return name
    if dbms == "mysql":
        return "`" + name + "`"
    if dbms == "mssql":
        return "[" + name + "]"
    return '"' + name.upper() + '"'


# SQL Server key-size budget: clustered keys <= 900 bytes, nonclustered <= 1700 bytes (NVARCHAR = 2 bytes/char).
MSSQL_BYTES = {"{vc80}": 160, "{date}": 3, "{num24_6}": 13, "{num12_6}": 9, "{vc8}": 16, "{vc16}": 32, "{vc40}": 80, "{asciistr}": 510, "{text}": 0, "{str}": 510, "{str64}": 128, "{str32}": 64, "{str1k}": 2000, "{long}": 8, "{int}": 4, "{small}": 2,
               "{bytes32}": 32, "{identity}": 8, "{ts}": 10, "{dec}": 9, "{money}": 8}


def pk_clause(dbms, table, cols, pk):
    kind = ""
    if dbms == "mssql":
        types = {c[0]: c[1] for c in cols}
        if sum(MSSQL_BYTES[types[k]] for k in pk) > 900:
            kind = " NONCLUSTERED"
    return f"  CONSTRAINT PK_{table[:27]} PRIMARY KEY{kind} ({', '.join(q(dbms, c) for c in pk)})"


def column_sql(dbms, col):
    name, token, nullability = col
    t = DIALECTS[dbms][token]
    return f"  {q(dbms, name)} {t}{(' ' + nullability) if nullability else ''}"


def render(dbms):
    out = ["--liquibase formatted sql", "",
           "-- GENERATED by tools/generate_changelogs.py from one portable catalogue. Do not edit by hand;",
           "-- add a new changeset file for any change to an applied table.", ""]
    for cs_id, comment, table, cols, pk, indexes in TABLES:
        out.append(f"--changeset sangam:{cs_id}-{table.lower()} dbms:{dbms}")
        out.append(f"--comment: {comment}")
        lines = [column_sql(dbms, c) for c in cols]
        types = {c[0]: c[1] for c in cols}
        # Oracle (ORA-02329): a TIMESTAMP WITH TIME ZONE column cannot be in a primary key or unique constraint. The
        # key becomes a function-based unique index on SYS_EXTRACT_UTC(<ts>): same uniqueness (one instant = one
        # key), the column keeps its type. Key columns must be NOT NULL in the catalogue (a unique index alone
        # would accept NULLs).
        oracle_ts_key = dbms == "oracle" and any(types[k] == "{ts}" for k in pk)
        if oracle_ts_key:
            nullable = [k for k in pk if "NOT NULL" not in (dict((c[0], c[2]) for c in cols)[k] or "")]
            if nullable:
                raise SystemExit(f"{table}: key columns {nullable} must be NOT NULL")
        else:
            lines.append(pk_clause(dbms, table, cols, pk))
        suffix = MYSQL_SUFFIX if dbms == "mysql" else ""
        out.append(f"CREATE TABLE {table} (\n" + ",\n".join(lines) + f"\n){suffix};")
        if oracle_ts_key:
            keycols = ", ".join(f"SYS_EXTRACT_UTC({q(dbms, k)})" if types[k] == "{ts}" else q(dbms, k) for k in pk)
            out.append(f"CREATE UNIQUE INDEX PK_{table[:27]} ON {table} ({keycols});")
        for ix in indexes:
            name, unique, icols = ix[0], ix[1], ix[2]
            override = ix[3] if len(ix) > 3 else {}
            if dbms in override:
                out.append(override[dbms])
            else:
                out.append(f"CREATE {'UNIQUE ' if unique else ''}INDEX {name} ON {table} "
                           f"({', '.join(q(dbms, c) for c in icols)});")
        out.append(f"--rollback DROP TABLE {table};")
        out.append("")
    for cs_id, comment, table, cols, indexes in ALTERS:
        out.append(f"--changeset sangam:{cs_id}-{table.lower()}-alter dbms:{dbms}")
        out.append(f"--comment: {comment}")
        for c in cols:
            out.append(add_column_sql(dbms, table, c))
        for name, unique, icols in indexes:
            out.append(f"CREATE {'UNIQUE ' if unique else ''}INDEX {name} ON {table} ({', '.join(icols)});")
        drops = [f"DROP INDEX {drop_index_sql(dbms, table, ix[0])};" if dbms != "mysql" and dbms != "mssql"
                 else (f"DROP INDEX {ix[0]} ON {table};") for ix in indexes]
        drops += [f"ALTER TABLE {table} DROP COLUMN {c[0]};" for c in cols]
        out.append("--rollback " + " ".join(drops))
        out.append("")
    return "\n".join(out)


def add_column_sql(dbms, table, col):
    """One ADD per statement: portable across PostgreSQL, Oracle, SQL Server, MySQL and H2."""
    name, token, nullability = col
    t = DIALECTS[dbms][token] + ((" " + nullability) if nullability else "")
    if dbms == "oracle":
        return f"ALTER TABLE {table} ADD ({name} {t});"
    if dbms == "mssql":
        return f"ALTER TABLE {table} ADD {name} {t};"
    return f"ALTER TABLE {table} ADD COLUMN {name} {t};"


def drop_index_sql(dbms, table, index):
    return index


def main():
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "main", "resources", "db", "changelog")
    for dbms in DIALECTS:
        d = os.path.join(base, dbms)
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "sangam-0001-baseline.sql"), "w", encoding="utf-8", newline="\n") as f:
            f.write(render(dbms))
    print(f"{len(TABLES)} tables + {len(ALTERS)} alter changesets x {len(DIALECTS)} dialects written under "
          f"{os.path.normpath(base)}")


if __name__ == "__main__":
    main()
